/// Returns a table for `P` whose instances keep the thread that calls `create`
/// as their main thread.
///
/// [`export_cabi!`](crate::export_cabi) answers it for a plugin that is not
/// `Send`, which may not leave the thread that made it.
#[doc(hidden)]
pub const fn plugin<P: Plugin>() -> &'static SeamPlugin {
    const { &table::<P>(create::<P>) }
}

/// Returns a table for `P` whose instances are bound to no thread.
///
/// Each main-thread call takes the plugin on loan, on any thread, as
/// [`SeamPlugin`] says. [`export_cabi!`](crate::export_cabi) answers it for a
/// plugin that is `Send`.
#[doc(hidden)]
pub const fn plugin_moving<P: Plugin + Send>() -> &'static SeamPlugin {
    const { &table::<P>(create_unbound::<P>) }
}

/// The table [`export_cabi!`](crate::export_cabi) answers for a plugin:
/// [`plugin_moving`] for one that is `Send`, [`plugin`] for one that is not.
///
/// The choice is made where the plugin's type is known: this inherent
/// constant exists for a `Send` plugin, and a path to it otherwise finds
/// [`BoundAtCreation`]'s.
#[doc(hidden)]
#[derive(Debug)]
pub struct Table<P>(PhantomData<fn() -> P>);

/// The table for a plugin that is not `Send`; see [`Table`].
#[doc(hidden)]
pub trait BoundAtCreation {
    /// [`plugin`]'s table.
    const TABLE: &'static SeamPlugin;
}

impl<P: Plugin> BoundAtCreation for Table<P> {
    const TABLE: &'static SeamPlugin = plugin::<P>();
}

impl<P: Plugin + Send> Table<P> {
    /// [`plugin_moving`]'s table.
    pub const TABLE: &'static SeamPlugin = plugin_moving::<P>();
}

/// `create` for a table: [`create`] or [`create_unbound`].
type Create = unsafe extern "C" fn(*const SeamHost) -> *mut SeamInstance;

const fn table<P: Plugin>(create: Create) -> SeamPlugin {
    SeamPlugin {
        abi_version: ABI_VERSION,
        layout_count: layout_count::<P>,
        layout: layout::<P>,
        create,
        destroy: destroy::<P>,
        param_count: param_count::<P>,
        param_info: param_info::<P>,
        get: get::<P>,
        set: set::<P>,
        text: text::<P>,
        parse: parse::<P>,
        activate: activate::<P>,
        deactivate: deactivate::<P>,
        idle: idle::<P>,
        latency: latency::<P>,
        tail: tail::<P>,
        save: save::<P>,
        load: load::<P>,
        reset: reset::<P>,
        process: process::<P>,
    }
}

/// Exports a [`Plugin`] through the C interface: the one symbol `seam_plugin`.
///
/// Use it once, at the root of a crate built as a static library for the JUCE
/// adapter. Keep it apart from `export_vst3!`: JUCE's own VST3 wrapper defines
/// the symbols that one does. This macro refuses to build a plugin that
/// declares no layout, or a crate built with `panic = "abort"`, under which a
/// panic ends the host.
///
/// # Examples
///
/// ```no_run
#[doc = include_str!("../../doc/gain.rs")]
/// seam_host::export_cabi!(Gain);
/// ```
#[macro_export]
#[cfg_attr(docsrs, doc(cfg(feature = "cabi")))]
macro_rules! export_cabi {
    ($plugin:ty) => {
        const _: () = ::std::assert!(
            !<$plugin as $crate::Plugin>::INFO.layouts.is_empty(),
            "a plugin declares at least one layout"
        );

        #[cfg(not(panic = "unwind"))]
        ::std::compile_error!(
            "the C interface needs panic = \"unwind\": with abort, a panic ends the host"
        );

        /// The plugin, as `seam.h` declares it.
        #[allow(unsafe_code, reason = "the entry point the adapter finds by name")]
        #[unsafe(no_mangle)]
        pub extern "C" fn seam_plugin() -> *const $crate::cabi::SeamPlugin {
            // A `Send` plugin's table, else the trait's (see `Table`).
            #[allow(
                unused_imports,
                reason = "unused for a `Send` plugin, whose table is the inherent constant"
            )]
            use $crate::cabi::BoundAtCreation as _;
            <$crate::cabi::Table<$plugin>>::TABLE
        }
    };
}

/// The instance behind a pointer.
///
/// # Safety
///
/// `pointer` is null, or came from `create::<P>` for this same `P` and has
/// not been freed by `destroy`. The reference is used only during the call
/// that passed `pointer`. The header lets `destroy` run only with no other
/// call into the instance in flight, or from a host callback inside `idle`.
/// There `release` finds the tick and leaks the instance. Either way, the
/// instance outlives the reference. `Instance` is `Sync`, so that call may
/// run on any thread.
unsafe fn instance<'a, P: Plugin>(pointer: *mut SeamInstance) -> Option<&'a Instance<P>> {
    // SAFETY: the caller's contract: a non-null `pointer` is the box
    // `create::<P>` made, so it casts back to a live `Instance<P>`.
    unsafe { pointer.cast::<Instance<P>>().as_ref() }
}

/// The parameter at a host's index.
fn param<P: Plugin>(instance: &Instance<P>, index: u32) -> Option<(ParamId, &ParamDecl)> {
    let set = instance.set();
    let id = set.id_at(usize::try_from(index).ok()?)?;
    Some((id, set.decl(id)))
}

/// # Safety
///
/// None: it takes nothing, and is `unsafe` only to fit
/// [`SeamPlugin::layout_count`].
unsafe extern "C" fn layout_count<P: Plugin>() -> u32 {
    u32::try_from(P::INFO.layouts.len()).unwrap_or(u32::MAX)
}

/// # Safety
///
/// As [`SeamPlugin::layout`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn layout<P: Plugin>(index: u32, out: *mut SeamLayout) -> bool {
    // SAFETY: the header's contract: `out` is null or valid for writing one
    // `SeamLayout` until this call returns, and nothing else reads it then.
    let Some(out) = (unsafe { out.as_mut() }) else {
        return false;
    };
    let Some(layout) = P::INFO.layouts.get(index as usize) else {
        return false;
    };
    let channels = |count: usize| u32::try_from(count).unwrap_or(u32::MAX);
    *out = SeamLayout {
        inputs: channels(layout.inputs),
        outputs: channels(layout.outputs),
    };
    true
}

/// # Safety
///
/// As [`SeamPlugin::create`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn create<P: Plugin>(host: *const SeamHost) -> *mut SeamInstance {
    guard(std::ptr::null_mut(), || {
        // SAFETY: the header's contract: `host` is null or valid for reading
        // one `SeamHost` during this call, which copies it at once.
        let host = unsafe { host.as_ref() }.copied().unwrap_or(SeamHost::NONE);
        Box::into_raw(Instance::<P>::new(Some(Callbacks(host)))).cast()
    })
}

/// # Safety
///
/// As [`SeamPlugin::create`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn create_unbound<P: Plugin + Send>(host: *const SeamHost) -> *mut SeamInstance {
    guard(std::ptr::null_mut(), || {
        // SAFETY: as in `create`.
        let host = unsafe { host.as_ref() }.copied().unwrap_or(SeamHost::NONE);
        Box::into_raw(Instance::<P>::new_unbound(
            Some(Callbacks(host)),
            &LOAN_WAIT,
        ))
        .cast()
    })
}

/// # Safety
///
/// As [`SeamPlugin::destroy`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn destroy<P: Plugin>(pointer: *mut SeamInstance) {
    // Not the instance's own guard, which the free would outlive. And the
    // closure holds the pointer, not a reference to the instance, which
    // would still be live while the instance is freed.
    guard((), || {
        // SAFETY: the header's contract: `pointer` is null or a live
        // instance from `create`, and no other call into it is in flight.
        let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
            return;
        };
        if instance.release() == Release::Free {
            // SAFETY: the pointer came from `create::<P>`'s box and is freed
            // once, here. `release` said nothing reaches it any more: it took
            // the plugin itself, outside a tick, on the main thread or with
            // no call on another thread holding it. The reference above is
            // not used again, and the header lets no other call into the
            // instance be in flight.
            drop(unsafe { Box::from_raw(pointer.cast::<Instance<P>>()) });
        }
    });
}

/// # Safety
///
/// As [`SeamPlugin::param_count`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn param_count<P: Plugin>(pointer: *mut SeamInstance) -> u32 {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    unsafe { instance::<P>(pointer) }.map_or(0, |instance| {
        u32::try_from(instance.set().len()).unwrap_or(u32::MAX)
    })
}

/// # Safety
///
/// As [`SeamPlugin::param_info`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn param_info<P: Plugin>(
    pointer: *mut SeamInstance,
    index: u32,
    out: *mut SeamParamInfo,
) -> bool {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, which no `destroy` frees during this call. `out` is
    // null or valid for writing one `SeamParamInfo` until it returns.
    let (Some(instance), Some(out)) = (unsafe { instance::<P>(pointer) }, unsafe { out.as_mut() })
    else {
        return false;
    };
    instance.guard(false, || {
        let Some((id, decl)) = param(instance, index) else {
            return false;
        };
        // Open: a stepped continuous range is to pass its count too, so AAX
        // gets the count a JUCE build gave it; it passes 0, as any
        // continuous one does.
        let (kind, steps) = match decl.kind {
            Kind::Continuous(_) => (KIND_CONTINUOUS, 0),
            Kind::Bool => (KIND_BOOL, decl.kind.steps()),
            Kind::Choice(_) => (KIND_CHOICE, decl.kind.steps()),
        };
        *out = SeamParamInfo {
            key: SeamStr::new(decl.key),
            name: SeamStr::new(decl.name),
            unit: SeamStr::new(decl.unit),
            group: SeamStr::new(decl.group),
            host_id: instance.set().host_id(id),
            kind,
            steps,
            flags: if decl.bypass { PARAM_BYPASS } else { 0 },
            default_normalized: decl.kind.normalize(decl.default_value()),
        };
        true
    })
}

/// # Safety
///
/// As [`SeamPlugin::get`] and `seam.h`'s pointer rules say.
#[cfg_attr(seam_rtsan, sanitize(realtime = "nonblocking"))]
unsafe extern "C" fn get<P: Plugin>(pointer: *mut SeamInstance, index: u32) -> f64 {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return 0.0;
    };
    // As for `set`: the audio thread may call it.
    let _audio = audio_thread::enter();
    instance.guard(0.0, || {
        param(instance, index).map_or(0.0, |(id, _)| instance.set().normalized(id))
    })
}

/// # Safety
///
/// As [`SeamPlugin::set`] and `seam.h`'s pointer rules say.
#[cfg_attr(seam_rtsan, sanitize(realtime = "nonblocking"))]
unsafe extern "C" fn set<P: Plugin>(pointer: *mut SeamInstance, index: u32, normalized: f64) {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return;
    };
    // The audio thread may call it, so a debug build checks it takes no
    // lock there.
    let _audio = audio_thread::enter();
    instance.guard((), || {
        if let Some((id, _)) = param(instance, index) {
            instance.host_write(id, normalized);
        }
    });
}

/// # Safety
///
/// As [`SeamPlugin::text`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn text<P: Plugin>(
    pointer: *mut SeamInstance,
    index: u32,
    normalized: f64,
    out: *mut CChar,
    capacity: usize,
) -> usize {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return 0;
    };
    instance.guard(0, || {
        let room = !out.is_null() && capacity > 0;
        let Some((_, decl)) = param(instance, index) else {
            if room {
                // SAFETY: the header's contract: `out`, non-null here, is
                // valid for writing `capacity` bytes during this call, and
                // `capacity` is at least 1 here.
                unsafe { *out = CChar(0) };
            }
            return 0;
        };
        let text = decl.format_real(decl.host_value(normalized));
        if !room {
            // A size query: the length, so the caller can make room.
            return text.len();
        }
        let length = text.floor_char_boundary(capacity - 1);
        // SAFETY: `out` is valid for writing `capacity` bytes during this
        // call (the header's contract) and `length` is less than `capacity`,
        // so the text and its terminator fit. `text` is a new `String`, so
        // the two cannot overlap.
        unsafe {
            std::ptr::copy_nonoverlapping(text.as_ptr(), out.cast::<u8>(), length);
            *out.add(length) = CChar(0);
        }
        text.len()
    })
}

/// # Safety
///
/// As [`SeamPlugin::parse`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn parse<P: Plugin>(
    pointer: *mut SeamInstance,
    index: u32,
    text: SeamStr,
    normalized: *mut f64,
) -> bool {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, which no `destroy` frees during this call. `normalized`
    // is null or valid for writing one `f64` until it returns.
    let (Some(instance), Some(normalized)) = (unsafe { instance::<P>(pointer) }, unsafe {
        normalized.as_mut()
    }) else {
        return false;
    };
    instance.guard(false, || {
        let Some((id, decl)) = param(instance, index) else {
            return false;
        };
        if text.data.is_null() && text.length > 0 {
            return false;
        }
        let bytes = if text.length == 0 {
            &[][..]
        } else {
            // SAFETY: a host's `SeamStr` lives for the call it is passed to
            // (the header's contract), so `data` is valid for reading
            // `length` bytes until this call returns. `data` is non-null
            // here, since a null one with a length was refused above.
            unsafe { std::slice::from_raw_parts(text.data.cast::<u8>(), text.length) }
        };
        let Ok(text) = std::str::from_utf8(bytes) else {
            return false;
        };
        match decl.parse_real(text, instance.set().value(id)) {
            Some(real) => {
                *normalized = decl.kind.normalize(real);
                true
            }
            None => false,
        }
    })
}

/// # Safety
///
/// As [`SeamPlugin::activate`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn activate<P: Plugin>(
    pointer: *mut SeamInstance,
    sample_rate: f64,
    max_frames: u32,
    layout: SeamLayout,
) -> bool {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return false;
    };
    instance.guard(false, || {
        let Some(main) = instance.main() else {
            return false;
        };
        let max_frames = usize::try_from(max_frames).unwrap_or(0);
        let layout = Layout::new(layout.inputs as usize, layout.outputs as usize);
        Setup::new(sample_rate, max_frames)
            .is_some_and(|setup| instance.activate(&main, setup, layout))
    })
}

/// # Safety
///
/// As [`SeamPlugin::deactivate`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn deactivate<P: Plugin>(pointer: *mut SeamInstance) {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return;
    };
    instance.guard((), || {
        if let Some(main) = instance.main() {
            let _ = instance.deactivate(&main);
        }
    });
}

/// # Safety
///
/// As [`SeamPlugin::idle`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn idle<P: Plugin>(pointer: *mut SeamInstance) {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return;
    };
    instance.idle();
}

/// # Safety
///
/// As [`SeamPlugin::latency`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn latency<P: Plugin>(pointer: *mut SeamInstance) -> u32 {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    unsafe { instance::<P>(pointer) }.map_or(0, Instance::<P>::latency)
}

/// # Safety
///
/// As [`SeamPlugin::tail`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn tail<P: Plugin>(pointer: *mut SeamInstance) -> u32 {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    unsafe { instance::<P>(pointer) }.map_or(TAIL_NONE, Instance::<P>::tail)
}

/// # Safety
///
/// As [`SeamPlugin::save`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn save<P: Plugin>(
    pointer: *mut SeamInstance,
    context: *mut c_void,
    write: Option<WriteFn>,
) -> bool {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let (Some(instance), Some(write)) = (unsafe { instance::<P>(pointer) }, write) else {
        return false;
    };
    instance.guard(false, || {
        let bytes = instance.saved().save();
        // SAFETY: the header's contract: `write` may be called with its
        // `context` during this call and does not unwind; `bytes` outlives
        // the call to it.
        unsafe { write(context, bytes.as_ptr(), bytes.len()) };
        true
    })
}

/// # Safety
///
/// As [`SeamPlugin::load`] and `seam.h`'s pointer rules say.
unsafe extern "C" fn load<P: Plugin>(
    pointer: *mut SeamInstance,
    data: *const u8,
    length: usize,
) -> bool {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    let Some(instance) = (unsafe { instance::<P>(pointer) }) else {
        return false;
    };
    instance.guard(false, || {
        if data.is_null() && length > 0 {
            return false;
        }
        let bytes = if length == 0 {
            &[][..]
        } else {
            // SAFETY: the header's contract: `data`, non-null here, is valid
            // for reading `length` bytes until this call returns.
            unsafe { std::slice::from_raw_parts(data, length) }
        };
        instance.saved().load(bytes).is_ok()
    })
}

/// # Safety
///
/// As [`SeamPlugin::reset`] and `seam.h`'s pointer rules say.
#[cfg_attr(seam_rtsan, sanitize(realtime = "nonblocking"))]
unsafe extern "C" fn reset<P: Plugin>(pointer: *mut SeamInstance) {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, and no `destroy` frees it during this call.
    if let Some(instance) = unsafe { instance::<P>(pointer) } {
        // As for `set`: the audio thread may call it.
        let _audio = audio_thread::enter();
        instance.request_reset();
    }
}

/// # Safety
///
/// As [`SeamPlugin::process`] and `seam.h`'s pointer rules say.
#[cfg_attr(seam_rtsan, sanitize(realtime = "nonblocking"))]
unsafe extern "C" fn process<P: Plugin>(
    pointer: *mut SeamInstance,
    block: *const SeamProcess,
) -> u32 {
    // SAFETY: the header's contract: `pointer` is null or a live instance
    // from `create`, which no `destroy` frees during this call. `block` is
    // null or valid for reading one `SeamProcess` until it returns.
    let (Some(instance), Some(block)) =
        (unsafe { instance::<P>(pointer) }, unsafe { block.as_ref() })
    else {
        return STATUS_CONTINUE;
    };
    // SAFETY: the header's contract for `SeamProcess`: each list is null or
    // holds its count of channel pointers for this call, as `channel_list`
    // requires. The inputs are only read, so casting their pointers to
    // `*mut` writes nothing.
    let (inputs, outputs) = unsafe {
        (
            channel_list(block.inputs.cast::<*mut f32>(), block.input_count),
            channel_list(block.outputs, block.output_count),
        )
    };
    // SAFETY: the header's contract for `SeamProcess`: each channel is null
    // or valid for `frames` floats (the outputs for writing too) until this
    // call returns. The host touches none of them meanwhile, and any two are
    // one buffer or share no float.
    let outcome = unsafe { instance.process(block.frames as usize, inputs, outputs, |_| {}) };
    match outcome {
        Outcome::Empty => STATUS_CONTINUE,
        Outcome::Silent => {
            // SAFETY: as above: `silence` writes only the output channels
            // the header lets this call write.
            unsafe { silence(block) };
            STATUS_CONTINUE
        }
        Outcome::Played(status) => status_code(status),
    }
}
